// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 time, uint256 blockNum) public {
        vm.assume(amount == 10 ether);
        vm.assume(time > block.timestamp);
        vm.warp(time);
        vm.roll(blockNum);
        // drive c through fallback
        (bool success, ) = address(c).call{value: amount}("");
        vm.assume(success); // only consider successful calls
        // after the call, pastBlockTime must be >= block.timestamp of the current transaction
        assertTrue(c.pastBlockTime() >= time);
    }
}

